// Tysiące punktów SVG zwalniają przeglądarkę: dni łączymy w tygodnie.
export function aggregateWeeks(points:readonly DailyPoint[]){
  const weeks:DailyPoint[]=[];
  points.forEach((point,index)=>{
    if(index%7===0)weeks.push({...point});
    else{
